const ACCOUNT_SID = 'AC0eed0a0301b825f8b65f07bc44522bac';
const AUTH_TOKEN = '4ba62cb7cc8cfd561eb27d0a7377dadc';
const FROM_NUMBER = '+19045696676';
const MESSAGE_BODY = $node["Get All Numbers from Row"].json.body;

// ===== INPUT (single row number) =====
const raw = $json.number;

const numbers = typeof raw === 'string'
  ? [raw.replace(/[^\d+]/g, '')]
  : [];

// Validate
const validNumbers = numbers.filter(n => n.startsWith('+') && n.length >= 11);

if (validNumbers.length === 0) {
  return [{
    json: {
      status: 'SKIPPED',
      reason: 'Invalid or empty phone number',
      raw
    }
  }];
}

// Twilio endpoint
const url = `https://api.twilio.com/2010-04-01/Accounts/${ACCOUNT_SID}/Messages.json`;
const authHeader = Buffer.from(`${ACCOUNT_SID}:${AUTH_TOKEN}`).toString('base64');

const results = [];

for (const to of validNumbers) {
  try {
    const body =
      `To=${encodeURIComponent(to)}` +
      `&From=${encodeURIComponent(FROM_NUMBER)}` +
      `&Body=${encodeURIComponent(MESSAGE_BODY)}`;

    const response = await this.helpers.httpRequest({
      method: 'POST',
      url,
      headers: {
        Authorization: `Basic ${authHeader}`,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body,
    });

    results.push({ to, status: 'SENT', sid: response.sid });

  } catch (err) {
    results.push({
      to,
      status: 'FAILED',
      error: err?.response?.body || err.message
    });
  }
}

return results.map(r => ({ json: r }));

