function clean(v) {
  return (v || "").toString().trim();
}

const owner = clean($json["Owner 1 First Name"]) || "there";
const address = clean($json["Address"]);
const city = clean($json["City"]);
const state = clean($json["State"]);

// Build location safely
const location = [
  address,
  city,
  state
].filter(Boolean).join(", ");

// Single-line SMS body (no \n)
const body = `Hi ${owner}, we’re reaching out regarding a property ${location} opportunity in your area. Would you be interested in discussing this? Please let me know if you are interested. Thanks!`;

return [
  {
    ...$json,
    body
  }
];
